@startuml

class User {
  +username : string
  +password : string
}

class Player extends User {}

class Admin extends User {}

class Game {
  +name : string
}

class Block {
  +color : string
  +points : int
}

class Level {
  +levelNumber : int
  +isRandom : boolean
  +startingArrangement : string
  +numberOfBlocks : int
  +minBallSpeed : float
  +speedIncreaseFactor : float
  +maxPaddleLength : float
  +minPaddleLength : float
}

class HallOfFameEntry {
  +totalScore : int
}

class BlockAssignment {
  +gridPosition : string
}

class PlayedGame {
  +livesRemaining : int
  +isPaused : boolean
}

Game "1" *-- "*" Level
Game "1" *-- "*" Block
Game "1" -- "0..1" Admin
Game "1" -- "1" HallOfFameEntry
Game "1" -- "*" PlayedGame
Level "1" *-- "*" BlockAssignment
Block "1" -- "*" BlockAssignment
Player "1" -- "*" PlayedGame
Player "1" -- "*" HallOfFameEntry

@enduml

